import bcrypt from 'bcrypt';  // npm install bcrypt

// WHY bcrypt (not SHA256/MD5):
// 1. Slow by design — cost factor makes brute force expensive
// 2. Built-in salt — prevents rainbow table attacks
// 3. Adaptive — increase cost as hardware gets faster

const SALT_ROUNDS = 12;  // 2^12 = 4096 iterations; adjust up as hardware improves
// Rule of thumb: should take ~300ms on your server
// 10 = 100ms, 12 = 400ms, 14 = 1.5s — higher is safer but slower on login

// Registration
async function registerUser(email: string, password: string) {
  // Check against breached passwords before hashing
  const isPwned = await checkHaveIBeenPwned(password);
  if (isPwned) {
    throw new Error('This password appeared in a data breach. Choose a different one.');
  }

  const hash = await bcrypt.hash(password, SALT_ROUNDS);
  // hash looks like: $2b$12$... (includes algorithm, cost, salt, and hash)
  await db.users.create({ email, passwordHash: hash });
}

// Login — constant-time comparison (bcrypt.compare is already constant-time)
async function loginUser(email: string, password: string) {
  const user = await db.users.findByEmail(email);

  // CRITICAL: Always run bcrypt.compare even if user not found
  // Otherwise, 'email not found' returns faster than 'wrong password'
  // — a timing side-channel that reveals valid email addresses
  const dummyHash = '$2b$12$invalidhashfortimingnormalization...';
  const hash = user?.passwordHash ?? dummyHash;

  const valid = await bcrypt.compare(password, hash);

  // Return identical error regardless of whether email or password was wrong
  if (!user || !valid) {
    throw new Error('Invalid email or password');
    // NOT: 'Email not found' or 'Wrong password' — those reveal too much
  }

  return user;
}

import rateLimit from 'express-rate-limit';  // npm install express-rate-limit
import RedisStore from 'rate-limit-redis';    // npm install rate-limit-redis

// IP-based rate limit for login — prevents brute force
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,  // 15 minutes
  max: 10,                    // 10 attempts per IP per window
  message: { error: 'Too many login attempts. Try again in 15 minutes.' },
  standardHeaders: true,  // Return RateLimit-* headers
  legacyHeaders: false,
  // In production: use Redis to share limits across multiple servers
  // store: new RedisStore({ client: redisClient }),
});

// Apply only to login endpoint
app.post('/api/auth/login', loginLimiter, loginHandler);

// Progressive account lockout (more sophisticated)
async function loginHandler(req, res) {
  const { email, password } = req.body;

  // Check if account is temporarily locked
  const failCount = await redis.get(`login_fails:${email}`) || 0;
  if (failCount >= 5) {
    const ttl = await redis.ttl(`login_fails:${email}`);
    return res.status(429).json({
      error: `Account temporarily locked. Try again in ${Math.ceil(ttl / 60)} minutes.`
    });
  }

  try {
    const user = await loginUser(email, password);
    await redis.del(`login_fails:${email}`);  // Reset on success
    // ... issue session
  } catch {
    // Increment failure counter with 30-minute expiry
    await redis.incr(`login_fails:${email}`);
    await redis.expire(`login_fails:${email}`, 30 * 60);
    res.status(401).json({ error: 'Invalid email or password' });
  }
}
